/**
 * Generated by tools/deco-pipeline/door-locks.py: the lock decos rendered with only one
 * keyhole showing (the deco's showLock(key_id), DoorView.as 243-244); key 0 is an unlocked
 * door, chains and keyholes hidden (hideLock(), DoorView.as 245-247). Do not edit.
 */
export const DOOR_LOCK_ART = Object.freeze({"door_asset_apartment_door_lock":[1,2,3,4,5],"door_asset_heights_door_lock":[0,1,2,5,8,10],"door_asset_wooden_door_lock":[0,9],"groddle_door_asset_groddle_wooden_door_lock":[1,2,3,4,5,10,12],"zutto_door_asset_wooden_door_lock":[0,7,9]});

/** The file for a door of `deco` that `keyId` opens (0: unlocked), or null (draw the plain deco). */
export function doorLockArt(deco, keyId) {
  const k = Number(keyId);
  return DOOR_LOCK_ART[deco]?.includes(k) ? `assets/decos/door-locks/${deco}__key${k}@1.5x.webp` : null;
}
